## 2. OpenID Connect Authorization Endpoint

```csharp
public class OpenIdConnectAuthorizationEndpoint : IOpenIdConnectAuthorizationEndpoint
{
    private readonly IUserDirectoryService _userDirectory;
    private readonly ITokenService _tokenService;
    private readonly IConfiguration _configuration;
    private readonly ILogger<OpenIdConnectAuthorizationEndpoint> _logger;

    public OpenIdConnectAuthorizationEndpoint(
        IUserDirectoryService userDirectory,
        ITokenService tokenService,
        IConfiguration configuration,
        ILogger<OpenIdConnectAuthorizationEndpoint> logger)
    {
        _userDirectory = userDirectory;
        _tokenService = tokenService;
        _configuration = configuration;
        _logger = logger;
    }

    public async Task<AuthorizationResponse> AuthorizeAsync(AuthorizationRequest request)
    {
        // Validate request parameters
        if (string.IsNullOrWhiteSpace(request.ClientId) ||
            string.IsNullOrWhiteSpace(request.ResponseType) ||
            string.IsNullOrWhiteSpace(request.RedirectUri))
        {
            return new AuthorizationResponse
            {
                Error = "invalid_request",
                ErrorDescription = "Missing required parameters"
            };
        }

        // Get user from session or authentication cookie
        var user = request.HttpContext.User;
        if (!user.Identity.IsAuthenticated)
        {
            return new AuthorizationResponse
            {
                Error = "unauthorized_client",
                ErrorDescription = "User not authenticated"
            };
        }

        // Get user from directory
        var directoryUser = await _userDirectory.GetUserByIdAsync(user.FindFirst(ClaimTypes.NameIdentifier)?.Value);
        if (directoryUser == null)
        {
            return new AuthorizationResponse
            {
                Error = "access_denied",
                ErrorDescription = "User not found in directory"
            };
        }

        // Check account status
        if (!directoryUser.IsActive)
        {
            return new AuthorizationResponse
            {
                Error = "account_disabled",
                ErrorDescription = "Account is disabled"
            };
        }

        if (directoryUser.IsLocked)
        {
            return new AuthorizationResponse
            {
                Error = "account_locked",
                ErrorDescription = "Account is locked"
            };
        }

        // Generate tokens
        var scopes = request.Scopes ?? new[] { "openid", "profile" };
        var accessToken = await _tokenService.GenerateAccessTokenAsync(directoryUser, scopes);

        // Build response
        var response = new AuthorizationResponse
        {
            AccessToken = accessToken,
            TokenType = "Bearer",
            ExpiresIn = _configuration.GetValue<int>("Jwt:ExpirationMinutes") * 60
        };

        // Add ID token if requested
        if (request.ResponseType.Contains("id_token"))
        {
            response.IdToken = GenerateIdToken(directoryUser);
        }

        return response;
        // TODO: Add refresh token generation if needed
    }

    private string GenerateIdToken(User user)
    {
        // Implementation would use JWT library to create ID token
        // with user claims and expiration
        return "generated.id.token";
    }
}

public class AuthorizationRequest
{
    public string ClientId { get; set; }
    public string ResponseType { get; set; }
    public string RedirectUri { get; set; }
    public string Scope { get; set; }
    public IEnumerable<string> Scopes => Scope?.Split(' ') ?? Array.Empty<string>();
    public string State { get; set; }
    public HttpContext HttpContext { get; set; }
}

public class AuthorizationResponse
{
    public string AccessToken { get; set; }
    public string IdToken { get; set; }
    public string RefreshToken { get; set; }
    public string TokenType { get; set; }
    public int ExpiresIn { get; set; }
    public string Error { get; set; }
    public string ErrorDescription { get; set; }
}
