## 3. User Directory Service

```csharp
public class UserDirectoryService : IUserDirectoryService
{
    private readonly IUserRepository _userRepository;
    private readonly IPasswordHasher<User> _passwordHasher;
    private readonly ILogger<UserDirectoryService> _logger;

    public UserDirectoryService(
        IUserRepository userRepository,
        IPasswordHasher<User> passwordHasher,
        ILogger<UserDirectoryService> logger)
    {
        _userRepository = userRepository;
        _passwordHasher = passwordHasher;
        _logger = logger;
    }

    public async Task<User> GetUserByIdAsync(string userId)
    {
        return await _userRepository.GetByIdAsync(userId);
    }

    public async Task<User> GetUserByUsernameAsync(string username)
    {
        return await _userRepository.GetByUsernameAsync(username);
    }

    public async Task<User> CreateUserAsync(string username, string password, string email)
    {
        if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
        {
            throw new ArgumentException("Username and password are required");
        }

        // Check if user already exists
        var existingUser = await GetUserByUsernameAsync(username);
        if (existingUser != null)
        {
            throw new InvalidOperationException("Username already exists");
        }

        var user = new User
        {
            Username = username,
            Email = email,
            IsActive = true,
            CreatedDate = DateTime.UtcNow
        };

        // Hash password
        user.PasswordHash = _passwordHasher.HashPassword(user, password);

        await _userRepository.AddAsync(user);
        return user;
    }

    public async Task<bool> ValidateCredentialsAsync(string username, string password)
    {
        var user = await GetUserByUsernameAsync(username);
        if (user == null)
        {
            return false;
        }

        if (!user.IsActive)
        {
            return false;
        }

        if (user.IsLocked)
        {
            return false;
        }

        return _passwordHasher.VerifyHashedPassword(user, user.PasswordHash, password) == PasswordVerificationResult.Success;
    }

    public async Task LockUserAsync(string userId)
    {
        var user = await GetUserByIdAsync(userId);
        if (user == null)
        {
            throw new KeyNotFoundException("User not found");
        }

        user.IsLocked = true;
        user.LockedUntil = DateTime.UtcNow.AddMinutes(30); // Default lock duration
        await _userRepository.UpdateAsync(user);
    }

    public async Task UnlockUserAsync(string userId)
    {
        var user = await GetUserByIdAsync(userId);
        if (user == null)
        {
            throw new KeyNotFoundException("User not found");
        }

        user.IsLocked = false;
        user.LockedUntil = null;
        await _userRepository.UpdateAsync(user);
    }

    public async Task<bool> IsAccountLockedAsync(string userId)
    {
        var user = await GetUserByIdAsync(userId);
        return user?.IsLocked ?? false;
    }
}

// Repository interface
public interface IUserRepository
{
    Task<User> GetByIdAsync(string id);
    Task<User> GetByUsernameAsync(string username);
    Task AddAsync(User user);
    Task UpdateAsync(User user);
}

// Password hashing implementation
public class PasswordHasher<User> : IPasswordHasher<User>
{
    private readonly HashAlgorithmName _algorithmName;

    public PasswordHasher(HashAlgorithmName algorithmName = HashAlgorithmName.HMACSHA256)
    {
        _algorithmName = algorithmName;
    }

    public PasswordVerificationResult VerifyHashedPassword(User user, string hashedPassword, string providedPassword)
    {
        if (string.IsNullOrEmpty(hashedPassword) || string.IsNullOrEmpty(providedPassword))
        {
            return PasswordVerificationResult.Failed;
        }

        var hashedProvided = HashPassword(user, providedPassword);
        return hashedProvided.SequenceEqual(Convert.FromBase64String(hashedPassword))
            ? PasswordVerificationResult.Success
            : PasswordVerificationResult.Failed;
    }

    public string HashPassword(User user, string password)
    {
        if (string.IsNullOrEmpty(password))
        {
            throw new ArgumentException("Password cannot be null or empty", nameof(password));
        }

        var salt = RandomNumberGenerator.GetBytes(16);
        var key = new Rfc2898DeriveBytes(password, salt, 100000);
        var hash = key.GetBytes(32);

        var saltedHash = new byte[salt.Length + hash.Length];
        Buffer.BlockCopy(salt, 0, saltedHash, 0, salt.Length);
        Buffer.BlockCopy(hash, 0, saltedHash, salt.Length, hash.Length);

        return Convert.ToBase64String(saltedHash);
    }
}
