## 4. Token Revocation Subsystem

```csharp
public class TokenRevocationService : ITokenRevocationService
{
    private readonly ITokenBlacklistRepository _tokenBlacklistRepository;
    private readonly ILogger<TokenRevocationService> _logger;

    public TokenRevocationService(
        ITokenBlacklistRepository tokenBlacklistRepository,
        ILogger<TokenRevocationService> logger)
    {
        _tokenBlacklistRepository = tokenBlacklistRepository;
        _logger = logger;
    }

    public async Task AddToBlacklistAsync(string token)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            throw new ArgumentException("Token cannot be null or empty", nameof(token));
        }

        var entry = new TokenBlacklistEntry
        {
            Token = token,
            RevokedAt = DateTime.UtcNow,
            RevokedBy = "system" // Could be enhanced with user context
        };

        await _tokenBlacklistRepository.AddAsync(entry);
    }

    public async Task<bool> IsTokenRevokedAsync(string token)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            return false;
        }

        return await _tokenBlacklistRepository.ExistsAsync(token);
    }

    public async Task<bool> RemoveFromBlacklistAsync(string token)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            return false;
        }

        return await _tokenBlacklistRepository.RemoveAsync(token);
    }
}

// Repository interface
public interface ITokenBlacklistRepository
{
    Task AddAsync(TokenBlacklistEntry entry);
    Task<bool> ExistsAsync(string token);
    Task<bool> RemoveAsync(string token);
    Task CleanupOldEntriesAsync(DateTime cutoffDate);
}
```

## 5. Token Service Implementation

```csharp
public class JwtTokenService : ITokenService
{
    private readonly IConfiguration _configuration;
    private readonly ITokenRevocationService _tokenRevocationService;
    private readonly ILogger<JwtTokenService> _logger;

    public JwtTokenService(
        IConfiguration configuration,
        ITokenRevocationService tokenRevocationService,
        ILogger<JwtTokenService> logger)
    {
        _configuration = configuration;
        _tokenRevocationService = tokenRevocationService;
        _logger = logger;
    }

    public async Task<string> GenerateAccessTokenAsync(User user, IEnumerable<string> scopes)
    {
        var claims = new List<Claim>
        {
            new Claim(JwtRegisteredClaimNames.Sub, user.Id),
            new Claim(JwtRegisteredClaimNames.UniqueName, user.Username),
            new Claim(JwtRegisteredClaimNames.Email, user.Email),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new Claim(JwtRegisteredClaimNames.Iat, DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString())
        };

        // Add scopes
        foreach (var scope in scopes)
        {
            claims.Add(new Claim(JwtRegisteredClaimNames.Scope, scope));
        }

        // Add user claims
        foreach (var claim in user.Claims)
        {
            claims.Add(new Claim(claim.Type, claim.Value));
        }

        var token = new JwtSecurityToken(
            issuer: _configuration["Jwt:Issuer"],
            audience: _configuration["Jwt:Audience"],
            claims: claims,
            expires: DateTime.UtcNow.AddMinutes(_configuration.GetValue<int>("Jwt:ExpirationMinutes")),
            signingCredentials: new SigningCredentials(
                new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_configuration["Jwt:Key"])),
                SecurityAlgorithms.HmacSha256));

        return new JwtSecurityTokenHandler().WriteToken(token);
    }

    public async Task<bool> ValidateTokenAsync(string token)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            return false;
        }

        // Check if token is revoked
        if (await _tokenRevocationService.IsTokenRevokedAsync(token))
        {
            return false;
        }

        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.UTF8.GetBytes(_configuration["Jwt:Key"]);

        try
        {
            tokenHandler.ValidateToken(token, new TokenValidationParameters
            {
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(key),
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidIssuer = _configuration["Jwt:Issuer"],
                ValidAudience = _configuration["Jwt:Audience"],
                ValidateLifetime = true,
                ClockSkew = TimeSpan.Zero
            }, out _);

            return true;
        }
        catch (SecurityTokenException)
        {
            return false;
        }
    }

    public async Task RevokeTokenAsync(string token)
    {
        await _tokenRevocationService.AddToBlacklistAsync(token);
    }
}
```

## 6. Dependency Injection Setup

```csharp
public static class IamServiceExtensions
{
    public static IServiceCollection AddEnterpriseIam(this IServiceCollection services, IConfiguration configuration)
    {
        // Configuration
        services.Configure<JwtOptions>(configuration.GetSection("Jwt"));

        // Services
        services.AddScoped<IUserDirectoryService, UserDirectoryService>();
        services.AddScoped<ITokenService, JwtTokenService>();
        services.AddScoped<ITokenRevocationService, TokenRevocationService>();
        services.AddScoped<IOpenIdConnectAuthorizationEndpoint, OpenIdConnectAuthorizationEndpoint>();

        // Repositories (implementation would depend on your data store)
        services.AddScoped<IUserRepository, UserRepository>();
        services.AddScoped<ITokenBlacklistRepository, TokenBlacklistRepository>();

        // Password hashing
        services.AddScoped<IPasswordHasher<User>, PasswordHasher<User>>();

        // JWT handling
        services.AddAuthentication(options =>
        {
            options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
            options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
        })
        .AddJwtBearer(options =>
        {
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidIssuer = configuration["Jwt:Issuer"],
                ValidAudience = configuration["Jwt:Audience"],
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(configuration["Jwt:Key"]))
            };
        });

        return services;
    }
}
